import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import PropertyCard from '../components/PropertyCard';
import HeroSearch from '../components/HeroSearch';
import EnquiryModal from '../components/EnquiryModal';
import { getProperties } from '../services/api';
import styles from './HomePage.module.css';

const CATEGORIES = [
  { id: 'apartment', title: 'Apartments', icon: '🏢', bg: '#E6F4EA' },
  { id: 'villa', title: 'Villas', icon: '🏡', bg: '#FEF3C7' },
  { id: 'plot', title: 'Plots / Land', icon: '🌿', bg: '#E0F2FE' },
  { id: 'commercial', title: 'Commercial', icon: '🏬', bg: '#F3E8FF' },
  { id: 'independent', title: 'Independent House', icon: '🏠', bg: '#DCFCE7' },
  { id: 'pg', title: 'PG / Hostel', icon: '🛋️', bg: '#FFF1F2' },
];

const CITIES = [
  { name: 'Bengaluru', image: 'https://images.unsplash.com/photo-1625134673337-519d4d10b313?w=600&q=80' },
  { name: 'Mumbai', image: 'https://images.unsplash.com/photo-1570168007204-dfb528c6958f?w=600&q=80' },
  { name: 'Hyderabad', image: 'https://images.unsplash.com/photo-1584443483978-5ec6c0ba7649?w=600&q=80' },
  { name: 'Chennai', image: 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?w=600&q=80' },
  { name: 'Pune', image: 'https://images.unsplash.com/photo-1587474260584-136574528ed5?w=600&q=80' },
  { name: 'Delhi', image: 'https://images.unsplash.com/photo-1587474260584-136574528ed5?w=600&q=80' },
];

export default function HomePage() {
  const navigate = useNavigate();
  const [properties, setProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [enquiryProp, setEnquiryProp] = useState(null);

  useEffect(() => {
    getProperties({ limit: 8 })
      .then(({ data }) => setProperties(data.properties || []))
      .catch(() => { })
      .finally(() => setLoading(false));
  }, []);

  return (
    <div>
      {/* Hero */}
      <HeroSearch />

      {/* Stats Banner */}
      {/* <div className={styles.statsBanner}> */}
      {/* <div className={`container ${styles.statsInner}`}>
          {[
            { label: 'Properties Listed', value: '50,000+' },
            { label: 'Cities Covered',    value: '100+'    },
            { label: 'Happy Buyers',      value: '25,000+' },
            { label: 'Verified Listings', value: '95%'     },
          ].map(s => (
            <div key={s.label} className={styles.stat}>
              <div className={styles.statValue}>{s.value}</div>
              <div className={styles.statLabel}>{s.label}</div>
            </div>
          ))}
        </div>
      </div> */}

      {/* Categories */}
      <section className={`container ${styles.section}`}>
        <div className={styles.sectionHeader}>
          <h2 className={styles.sectionTitle}>Explore by Category</h2>
        </div>
        <div className={styles.categoriesGrid}>
          {CATEGORIES.map(cat => (
            <button
              key={cat.id}
              className={styles.categoryCard}
              style={{ '--cat-bg': cat.bg }}
              onClick={() => navigate(`/search?propertyType=${cat.id}`)}
            >
              <div className={styles.catIcon}>{cat.icon}</div>
              <div className={styles.catTitle}>{cat.title}</div>
            </button>
          ))}
        </div>
      </section>

      {/* Popular Properties */}
      <section className={`container ${styles.section}`}>
        <div className={styles.sectionHeader}>
          <div>
            <h2 className={styles.sectionTitle}>Popular Properties</h2>
            <p className={styles.sectionSub}>Curated homes in prime localities</p>
          </div>
          <button className={styles.seeAll} onClick={() => navigate('/search')}>See All →</button>
        </div>
        {loading ? (
          <div className={styles.loading}>Loading properties...</div>
        ) : properties.length === 0 ? (
          <div className={styles.empty}>
            <div className={styles.emptyIcon}>🏠</div>
            <div className={styles.emptyTitle}>No Properties Yet</div>
            <div className={styles.emptySub}>Be the first to list a property!</div>
            <button className={styles.postBtn} onClick={() => navigate('/post-property')}>+ Post a Property</button>
          </div>
        ) : (
          <div className={styles.propertiesGrid}>
            {properties.map(p => (
              <PropertyCard key={p.id || p._id} property={p} onEnquire={setEnquiryProp} />
            ))}
          </div>
        )}
      </section>

      {/* City Section */}
      <section className={`container ${styles.section}`}>
        <div className={styles.sectionHeader}>
          <div>
            <h2 className={styles.sectionTitle}>Find Properties by City</h2>
            <p className={styles.sectionSub}>Top urban hubs with high capital appreciation</p>
          </div>
        </div>
        <div className={styles.citiesGrid}>
          {CITIES.map(c => (
            <button
              key={c.name}
              className={styles.cityTile}
              onClick={() => navigate(`/search?city=${c.name}`)}
              style={{ backgroundImage: `url(${c.image})` }}
            >
              <div className={styles.cityGradient} />
              <div className={styles.cityName}>{c.name}</div>
            </button>
          ))}
        </div>
      </section>

      {/* Commercial Banner */}
      <section className={`container ${styles.section}`}>
        <div className={styles.commercialCard}>
          <div className={styles.commercialLeft}>
            <span className={styles.commercialTag}>INSTITUTIONAL ASSETS</span>
            <h2 className={styles.commercialTitle}>Commercial Real Estate Spotlight</h2>
            <p className={styles.commercialBody}>
              Pre-leased Grade-A corporate towers, co-working suites & high-street retail spaces with guaranteed long leases.
            </p>
            <button className={styles.commercialBtn} onClick={() => navigate('/search?buildingType=Commercial')}>
              Explore Commercial →
            </button>
          </div>
          <div className={styles.commercialMetrics}>
            {[
              { value: '8–12%', label: 'Avg. Rental Yield' },
              { value: '5+', label: 'Year Lock-in' },
              { value: 'Grade A', label: 'Office Spaces' },
            ].map(m => (
              <div key={m.label} className={styles.metric}>
                <div className={styles.metricValue}>{m.value}</div>
                <div className={styles.metricLabel}>{m.label}</div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Post Property Banner */}
      <section className={`container ${styles.section}`}>
        <div className={styles.postBanner}>
          <div>
            <h2 className={styles.postBannerTitle}>List Your Property for Free</h2>
            <p className={styles.postBannerSub}>Reach thousands of genuine buyers & tenants</p>
          </div>
          <button className={styles.postBannerBtn} onClick={() => navigate('/post-property')}>
            Post Property Free →
          </button>
        </div>
      </section>

      {/* Enquiry Modal */}
      {enquiryProp && (
        <EnquiryModal property={enquiryProp} onClose={() => setEnquiryProp(null)} />
      )}
    </div>
  );
}
